WITH EmployeesByDepartment AS (SELECT dept_id, ROUND((100 * SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l3 FROM employees WHERE LENGTH(email) >= 7 GROUP BY dept_id) SELECT departments.id, departments.dept_name, EmployeesByDepartment.pct_l3 FROM departments INNER JOIN EmployeesByDepartment ON departments.id = EmployeesByDepartment.dept_id ORDER BY departments.id DESC, EmployeesByDepartment.pct_l3 DESC LIMIT 5;
